<boltAction type="file" filePath="src/components/MemberCard.jsx">import { ChevronRight } from 'lucide-react';

function formatLastVisit(iso) {
  const d = new Date(iso);
  const now = new Date();
  const diffDays = Math.floor((now.setHours(0, 0, 0, 0) - new Date(d).setHours(0, 0, 0, 0)) / 86400000);

  if (diffDays === 0) return '오늘 방문';
  if (diffDays === 1) return '어제 방문';
  return `${diffDays}일 전 방문`;
}

function getRemainingColor(remaining) {
  if (remaining <= 0) return 'var(--err)';
  if (remaining <= 3) return 'var(--warn)';
  return 'inherit';
}

function MemberCard({ member, onClick }) {
  const isLow = member.remaining <= 0;
  const isFew = member.remaining > 0 && member.remaining <= 3;
  const isStale = (() => {
    const diffDays = Math.floor((new Date().setHours(0, 0, 0, 0) - new Date(member.lastVisit).setHours(0, 0, 0, 0)) / 86400000);
    return diffDays >= 30;
  })();

  return (
    <button
      className="cr-card cr-row-16"
      onClick={onClick}
      style={{
        width: '100%',
        alignItems: 'center',
        justifyContent: 'space-between',
        cursor: 'pointer',
        textAlign: 'left',
        transition: 'background-color 180ms ease-out, transform 180ms ease-out',
      }}
      onMouseEnter={(e) => (e.currentTarget.style.transform = 'translateY(-2px)')}
      onMouseLeave={(e) => (e.currentTarget.style.transform = 'translateY(0)')}
    >
      <div className="cr-stack-4" style={{ flex: 1, minWidth: 0 }}>
        <div className="cr-row-8" style={{ alignItems: 'center' }}>
          <span className="cr-body" style={{ fontWeight: 600 }}>{member.name}</span>
          {isLow && <span className="cr-badge err">잔여 없음</span>}
          {!isLow && isStale && <span className="cr-badge warn">장기 미방문</span>}
        </div>
        <span className="cr-caption" style={{ color: 'var(--muted)' }}>{member.phone}</span>
      </div>
      <div className="cr-row-16" style={{ alignItems: 'center', flexShrink: 0 }}>
        <div className="cr-stack-4" style={{ textAlign: 'right' }}>
          <span
            className="cr-body"
            style={{
              fontWeight: 700,
              fontVariantNumeric: 'tabular-nums',
              color: getRemainingColor(member.remaining),
            }}
          >
            잔여 {member.remaining}회
          </span>
          <span className="cr-caption" style={{ color: 'var(--muted)' }}>{formatLastVisit(member.lastVisit)}</span>
        </div>
        <ChevronRight size={18} style={{ color: 'var(--muted)' }} />
      </div>
    </button>
  );
}

export default MemberCard;
</boltAction>
<boltAction type="file" filePath="src/pages/MemberDetailPage.jsx">import { useMemo, useState } from 'react';
import { ArrowLeft, Plus, Minus, Phone, Calendar, Trash2 } from 'lucide-react';

function formatDate(iso) {
  const d = new Date(iso);
  return `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;
}

function getRemainingColor(remaining) {
  if (remaining <= 0) return 'var(--err)';
  if (remaining <= 3) return 'var(--warn)';
  return 'inherit';
}

function MemberDetailPage({ member, logs, onBack, onUse, onCharge, onDelete }) {
  const [chargeAmount, setChargeAmount] = useState('10');
  const [showChargeInput, setShowChargeInput] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  const sortedLogs = useMemo(
    () => [...logs].sort((a, b) => (a.at < b.at ? 1 : -1)),
    [logs],
  );

  const isEmpty = member.remaining <= 0;
  const isFew = member.remaining > 0 && member.remaining <= 3;
  const remainingColor = getRemainingColor(member.remaining);

  function handleCharge() {
    const amount = parseInt(chargeAmount, 10);
    if (!amount || amount <= 0) return;
    onCharge(amount);
    setShowChargeInput(false);
    setChargeAmount('10');
  }

  return (
    <div className="cr-page">
      <section className="cr-section cr-stack-24">
        <button
          onClick={onBack}
          className="cr-row-8"
          style={{ alignItems: 'center', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
        >
          <ArrowLeft size={18} style={{ color: 'var(--muted)' }} />
          <span className="cr-caption" style={{ color: 'var(--muted)' }}>목록으로</span>
        </button>

        <div className="cr-card cr-stack-16">
          <div className="cr-stack-4">
            <h1 className="cr-h1">{member.name}</h1>
            <div className="cr-row-8" style={{ alignItems: 'center' }}>
              <Phone size={14} style={{ color: 'var(--muted)' }} />
              <span className="cr-caption" style={{ color: 'var(--muted)' }}>{member.phone}</span>
            </div>
          </div>

          <div className="cr-grid-2">
            <div className="cr-stack-4">
              <div className="cr-row-8" style={{ alignItems: 'center' }}>
                <span className="cr-caption" style={{ color: 'var(--muted)' }}>잔여 횟수</span>
                {isEmpty && <span className="cr-badge err">부족</span>}
                {isFew && <span className="cr-badge warn">임박</span>}
              </div>
              <span
                className="cr-display"
                style={{ fontVariantNumeric: 'tabular-nums', color: remainingColor }}
              >
                {member.remaining}회
              </span>
            </div>
            <div className="cr-stack-4">
              <span className="cr-caption" style={{ color: 'var(--muted)' }}>누적 충전</span>
              <span className="cr-h2" style={{ fontVariantNumeric: 'tabular-nums' }}>{member.totalCharged}회</span>
            </div>
          </div>

          <div className="cr-row-8">
            <button
              className="cr-btn outline"
              style={{ flex: 1 }}
              onClick={() => onUse()}
              disabled={member.remaining <= 0}
            >
              <Minus size={16} />
              방문 처리 (1회 차감)
            </button>
            <button className="cr-btn" style={{ flex: 1 }} onClick={() => setShowChargeInput((v) => !v)}>
              <Plus size={16} />
              충전하기
            </button>
          </div>

          {showChargeInput && (
            <div className="cr-row-8" style={{ alignItems: 'center' }}>
              <input
                className="cr-input"
                type="number"
                min="1"
                value={chargeAmount}
                onChange={(e) => setChargeAmount(e.target.value)}
                style={{ flex: 1 }}
                placeholder="충전 횟수"
              />
              <button className="cr-btn" onClick={handleCharge}>확인</button>
            </div>
          )}
        </div>

        <div className="cr-stack-16">
          <span className="cr-eyebrow">방문·충전 기록</span>
          {sortedLogs.length === 0 ? (
            <p className="cr-caption" style={{ color: 'var(--muted)' }}>아직 기록이 없어요</p>
          ) : (
            <div className="cr-stack-8">
              {sortedLogs.map((log) => (
                <div key={log.id} className="cr-card cr-row-16" style={{ alignItems: 'center', justifyContent: 'space-between' }}>
                  <div className="cr-row-8" style={{ alignItems: 'center' }}>
                    <Calendar size={14} style={{ color: 'var(--muted)' }} />
                    <span className="cr-caption" style={{ color: 'var(--muted)' }}>{formatDate(log.at)}</span>
                  </div>
                  <span
                    className="cr-body"
                    style={{
                      fontWeight: 600,
                      color: log.type === 'charge' ? 'var(--ok)' : 'inherit',
                      fontVariantNumeric: 'tabular-nums',
                    }}
                  >
                    {log.type === 'charge' ? `+${log.amount}회 충전` : `-${log.amount}회 방문`}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="cr-stack-8">
          {!confirmDelete ? (
            <button
              className="cr-btn outline"
              onClick={() => setConfirmDelete(true)}
              style={{ color: 'var(--err)', borderColor: 'var(--err)' }}
            >
              <Trash2 size={16} />
              회원 삭제하기
            </button>
          ) : (
            <div className="cr-card cr-stack-16" style={{ borderColor: 'var(--err)' }}>
              <p className="cr-body">정말 삭제할까요? 되돌릴 수 없어요.</p>
              <div className="cr-row-8">
                <button className="cr-btn outline" style={{ flex: 1 }} onClick={() => setConfirmDelete(false)}>
                  취소
                </button>
                <button className="cr-btn danger" style={{ flex: 1 }} onClick={onDelete}>
                  삭제하기
                </button>
              </div>
            </div>
          )}
        </div>
      </section>
    </div>
  );
}

export default MemberDetailPage;
</boltAction>
</boltArtifact>

목록과 상세 화면 모두에서 잔여 횟수가 0이면 빨강, 3회 이하면 주황(경고), 그 이상이면 기본 색으로 표시돼요.

다음으로 이런 것도 해볼 수 있어요:
