import { useEffect, useState, useCallback } from 'react';
import { Settings, Trash2, X } from 'lucide-react';
import { db, isCloudStorageEnabled } from './lib/coralred-storage.js';
import { buildSeedMembers, buildSeedLogsFor } from './lib/seedData.js';
import HomePage from './pages/HomePage.jsx';
import MemberDetailPage from './pages/MemberDetailPage.jsx';
import AddMemberPage from './pages/AddMemberPage.jsx';
import Toast from './components/Toast.jsx';

const SEED_FLAG_KEY = 'gym_seeded_v1';

function App() {
  const [members, setMembers] = useState([]);
  const [logs, setLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [view, setView] = useState({ name: 'home' });
  const [toast, setToast] = useState(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [hasSeedData, setHasSeedData] = useState(false);

  const loadAll = useCallback(async () => {
    const [memberRes, logRes] = await Promise.all([
      db.list('members', { limit: 100 }),
      db.list('logs', { limit: 500 }),
    ]);
    setMembers(memberRes.items.map((it) => ({ id: it.id, ...it.data })));
    setLogs(logRes.items.map((it) => ({ id: it.id, ...it.data })));
  }, []);

  useEffect(() => {
    async function init() {
      setIsLoading(true);

      const existing = await db.list('members', { limit: 1 });

      if (existing.items.length === 0) {
        const seedMembers = buildSeedMembers();

        for (const seedMember of seedMembers) {
          const created = await db.create('members', {
            name: seedMember.name,
            phone: seedMember.phone,
            remaining: seedMember.remaining,
            totalCharged: seedMember.totalCharged,
            lastVisit: seedMember.lastVisit,
          });

          const seedLogs = buildSeedLogsFor(created.id, seedMember);

          for (const log of seedLogs) {
            await db.create('logs', log);
          }
        }

        setHasSeedData(true);
      } else {
        try {
          setHasSeedData(localStorage.getItem(SEED_FLAG_KEY) !== 'cleared');
        } catch {
          setHasSeedData(true);
        }
      }

      await loadAll();
      setIsLoading(false);
    }

    init();
  }, [loadAll]);

  function showToast(message, type = 'ok') {
    setToast({ message, type, key: Date.now() });
  }

  async function handleAddMember({ name, phone, initialCount }) {
    try {
      await db.create('members', {
        name,
        phone,
        remaining: initialCount,
        totalCharged: initialCount,
        lastVisit: new Date().toISOString(),
      });
      await loadAll();
      setView({ name: 'home' });
      showToast('회원이 등록됐어요');
    } catch (e) {
      showToast(e.message || '등록하다가 문제가 생겼어요', 'err');
    }
  }

  async function handleUse(memberId) {
    const member = members.find((m) => m.id === memberId);
    if (!member || member.remaining <= 0) return;

    try {
      const updatedData = {
        name: member.name,
        phone: member.phone,
        remaining: member.remaining - 1,
        totalCharged: member.totalCharged,
        lastVisit: new Date().toISOString(),
      };
      await db.update('members', memberId, updatedData);
      await db.create('logs', { memberId, type: 'use', amount: 1, memo: '방문', at: new Date().toISOString() });
      await loadAll();
      showToast('방문 처리됐어요');
    } catch (e) {
      showToast(e.message || '처리하다가 문제가 생겼어요', 'err');
    }
  }

  async function handleCharge(memberId, amount) {
    const member = members.find((m) => m.id === memberId);
    if (!member) return;

    try {
      const updatedData = {
        name: member.name,
        phone: member.phone,
        remaining: member.remaining + amount,
        totalCharged: member.totalCharged + amount,
        lastVisit: member.lastVisit,
      };
      await db.update('members', memberId, updatedData);
      await db.create('logs', { memberId, type: 'charge', amount, memo: '충전', at: new Date().toISOString() });
      await loadAll();
      showToast(`${amount}회 충전됐어요`);
    } catch (e) {
      showToast(e.message || '처리하다가 문제가 생겼어요', 'err');
    }
  }

  async function handleDeleteMember(memberId) {
    try {
      await db.remove('members', memberId);
      await loadAll();
      setView({ name: 'home' });
      showToast('회원이 삭제됐어요');
    } catch (e) {
      showToast(e.message || '삭제하다가 문제가 생겼어요', 'err');
    }
  }

  async function handleClearSeedData() {
    try {
      for (const member of members) {
        await db.remove('members', member.id);
      }
      for (const log of logs) {
        await db.remove('logs', log.id);
      }
      try {
        localStorage.setItem(SEED_FLAG_KEY, 'cleared');
      } catch {
        // localStorage 접근 불가 시 무시
      }
      setHasSeedData(false);
      setSettingsOpen(false);
      await loadAll();
      showToast('예시 데이터를 지웠어요');
    } catch (e) {
      showToast(e.message || '삭제하다가 문제가 생겼어요', 'err');
    }
  }

  const selectedMember = view.name === 'detail' ? members.find((m) => m.id === view.memberId) : null;
  const selectedLogs = selectedMember ? logs.filter((l) => l.memberId === selectedMember.id) : [];

  return (
    <div style={{ minHeight: '100vh', paddingBottom: '80px', position: 'relative' }}>
      {!isCloudStorageEnabled && (
        <div style={{ position: 'sticky', top: 0, zIndex: 30, display: 'flex', justifyContent: 'center', padding: '8px 0' }}>
          <span className="cr-badge warn">데이터가 이 기기에만 저장돼요</span>
        </div>
      )}

      <div
        style={{
          position: 'fixed',
          top: '16px',
          right: '16px',
          zIndex: 30,
        }}
      >
        <button
          onClick={() => setSettingsOpen(true)}
          aria-label="설정"
          style={{
            width: '40px',
            height: '40px',
            borderRadius: '999px',
            border: '1px solid var(--border)',
            background: 'var(--surface)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
          }}
        >
          <Settings size={18} style={{ color: 'var(--muted)' }} />
        </button>
      </div>

      {view.name === 'home' && (
        <HomePage
          members={members}
          isLoading={isLoading}
          onSelectMember={(id) => setView({ name: 'detail', memberId: id })}
          onAddMember={() => setView({ name: 'add' })}
        />
      )}

      {view.name === 'detail' && selectedMember && (
        <MemberDetailPage
          member={selectedMember}
          logs={selectedLogs}
          onBack={() => setView({ name: 'home' })}
          onUse={() => handleUse(selectedMember.id)}
          onCharge={(amount) => handleCharge(selectedMember.id, amount)}
          onDelete={() => handleDeleteMember(selectedMember.id)}
        />
      )}

      {view.name === 'add' && (
        <AddMemberPage onBack={() => setView({ name: 'home' })} onSubmit={handleAddMember} />
      )}

      {settingsOpen && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.3)',
            zIndex: 40,
            display: 'flex',
            alignItems: 'flex-end',
            justifyContent: 'center',
          }}
          onClick={() => setSettingsOpen(false)}
        >
          <div
            className="cr-overlay cr-stack-16"
            style={{ width: '100%', maxWidth: '480px', borderRadius: '12px 12px 0 0', padding: '24px' }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="cr-row-16" style={{ alignItems: 'center', justifyContent: 'space-between' }}>
              <span className="cr-h2">설정</span>
              <button
                onClick={() => setSettingsOpen(false)}
                style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
                aria-label="닫기"
              >
                <X size={20} style={{ color: 'var(--muted)' }} />
              </button>
            </div>

            {hasSeedData && (
              <div className="cr-stack-8">
                <span className="cr-caption" style={{ color: 'var(--muted)' }}>예시 데이터예요</span>
                <button className="cr-btn outline" onClick={handleClearSeedData}>
                  <Trash2 size={16} />
                  예시 데이터 지우기
                </button>
              </div>
            )}

            <p className="cr-caption" style={{ color: 'var(--muted)' }}>
              헬스장 회원 관리 · 총 {members.length}명
            </p>
          </div>
        </div>
      )}

      {toast && <Toast key={toast.key} message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
}

export default App;

