export function buildSeedLogsFor(memberId, memberSeed) {
  const today = new Date();

  function daysAgo(n) {
    const d = new Date(today);
    d.setDate(d.getDate() - n);
    return d.toISOString();
  }

  const logs = [
    { memberId, type: 'charge', amount: memberSeed.totalCharged, memo: '충전', at: daysAgo(40) },
  ];

  const used = memberSeed.totalCharged - memberSeed.remaining;
  let remainingToUse = used;
  let dayOffset = 30;

  while (remainingToUse > 0 && dayOffset > 0) {
    logs.push({ memberId, type: 'use', amount: 1, memo: '방문', at: daysAgo(dayOffset) });
    remainingToUse -= 1;
    dayOffset -= 3;
  }

  logs.push({ memberId, type: 'use', amount: 1, memo: '방문', at: memberSeed.lastVisit });

  return logs;
}

